// Generated by npm run sync:domain; edit shared/structure-plan.js instead.
// Canonical domain rules; deployment copies are generated by sync-domain.mjs.
const OPENINGS = [
  { value: 'pending', label: '待工程师确认' },
  { value: 'fixed', label: '固定 / 不开启' },
  { value: 'sliding', label: '推拉' },
  { value: 'inward', label: '内开' },
  { value: 'outward', label: '外开' },
  { value: 'other', label: '其他（文字说明）' },
];
const PLAN_LIMITS = { faces: 6, cells: 12 };
const fail = message => { const error = new Error(message); error.code = 'INVALID_ARGUMENT'; throw error; };
function text(value, max, label, required = false) {
  if (value !== undefined && typeof value !== 'string') fail(label + '格式不正确。');
  const result = (value || '').trim();
  if (result.length > max || (required && !result)) fail('请检查' + label + '及字数。');
  return result;
}
function dimension(value, label) {
  if (value === '' || value === undefined || value === null) return undefined;
  if (!['string', 'number'].includes(typeof value)) fail(label + '应为毫米正数。');
  const number = Number(value);
  if (!Number.isFinite(number) || number <= 0 || number > 1000000) fail(label + '应为有效的毫米正数。');
  return number;
}
function dimensions(row, label) {
  const result = {};
  for (const field of ['widthMm', 'heightMm']) {
    const value = dimension(row[field], label + (field === 'widthMm' ? '宽度' : '高度'));
    if (value !== undefined) result[field] = value;
  }
  return result;
}
function array(value, max, label) {
  if (value === undefined) return [];
  if (!Array.isArray(value) || value.length > max) fail(label + '数量超出限制或格式不正确。');
  return value;
}
function key(value, seen, label) {
  if (typeof value !== 'string' || !/^[a-zA-Z0-9_-]{1,60}$/.test(value) || seen.has(value)) fail(label + '标识不正确或重复。');
  seen.add(value);
  return value;
}
function normalizeStructurePlan(input) {
  if (input === undefined || input === null) return null;
  if (!input || typeof input !== 'object' || Array.isArray(input) || input.version !== 1) fail('结构方案版本不正确。');
  const faceKeys = new Set();
  const faces = array(input.faces, PLAN_LIMITS.faces, '安装面').map(face => {
    if (!face || typeof face !== 'object') fail('安装面格式不正确。');
    const cellKeys = new Set();
    const cells = array(face.cells, PLAN_LIMITS.cells, '分格').map(cell => {
      if (!cell || typeof cell !== 'object') fail('分格格式不正确。');
      const opening = cell.opening === undefined ? 'pending' : cell.opening;
      if (!OPENINGS.some(item => item.value === opening)) fail('开启方式不正确。');
      return { id: key(cell.id, cellKeys, '分格'), name: text(cell.name, 60, '分格名称', true), ...dimensions(cell, '分格'), opening, direction: text(cell.direction, 200, '开启方向'), notes: text(cell.notes, 400, '分格说明') };
    });
    return { id: key(face.id, faceKeys, '安装面'), name: text(face.name, 60, '安装面名称', true), ...dimensions(face, '安装面'), corner: text(face.corner, 300, '转角关系'), obstacles: text(face.obstacles, 500, '避让要求'), cells };
  });
  const result = { version: 1, faces, glass: text(input.glass, 300, '玻璃配置'), hardware: text(input.hardware, 300, '五金要求'), constraints: text(input.constraints, 1000, '禁止改变项') };
  // Keep old requirement hashes unchanged until an engineer actually adds a plan.
  return faces.length || result.glass || result.hardware || result.constraints ? result : null;
}
function structureIssues(plan) {
  if (!plan) return [];
  const issues = [];
  for (const [index, face] of plan.faces.entries()) {
    if (!face.widthMm || !face.heightMm) issues.push(face.name + '：总宽 / 高待确认');
    if (index > 0 && !face.corner) issues.push(face.name + '：与前一安装面的转角关系待确认');
    if (!face.cells.length) issues.push(face.name + '：至少记录一个分格或整面单元');
    for (const cell of face.cells) {
      const prefix = face.name + ' / ' + cell.name + '：';
      if (!cell.widthMm || !cell.heightMm) issues.push(prefix + '分格宽 / 高待确认');
      if (cell.opening === 'pending') issues.push(prefix + '开启方式待确认');
      else if (cell.opening !== 'fixed' && !cell.direction) issues.push(prefix + '开启方向 / 操作说明待确认');
    }
  }
  return issues;
}
function formatStructurePlan(plan) {
  if (!plan) return '';
  const size = row => '宽 ' + (row.widthMm || '待确认') + ' × 高 ' + (row.heightMm || '待确认') + ' mm';
  const lines = [];
  for (const face of plan.faces) {
    lines.push('安装面 ' + face.name + '：' + size(face));
    if (face.corner) lines.push('转角 / 相邻关系：' + face.corner);
    if (face.obstacles) lines.push('避让：' + face.obstacles);
    for (const cell of face.cells) {
      const opening = OPENINGS.find(item => item.value === cell.opening);
      lines.push('分格 ' + cell.name + '：' + size(cell) + '；' + (opening ? opening.label : '待确认') + (cell.direction ? '；方向：' + cell.direction : '') + (cell.notes ? '；说明：' + cell.notes : ''));
    }
  }
  if (plan.glass) lines.push('玻璃配置：' + plan.glass);
  if (plan.hardware) lines.push('五金要求：' + plan.hardware);
  if (plan.constraints) lines.push('禁止改变项：' + plan.constraints);
  return lines.join('\n');
}
module.exports = { OPENINGS, PLAN_LIMITS, normalizeStructurePlan, structureIssues, formatStructurePlan };
